213	#[cfg(test)]
214	mod tests {
215	    //! `row_to_domain_event` unit tests (SMA-446 Slice B Task B8, review finding, Fix 3): the
216	    //! three malformed-row error branches its own doc comment enumerates — an unrecognized
217	    //! `event_type` wire string, invalid `payload` JSON, and an out-of-range `schema_version`
218	    //! — each return `Err`, plus a well-formed row maps to the exact `DomainEvent` its fields
219	    //! describe. No DB needed: `event_outbox::Model` is hand-built, never persisted.
220	    use super::*;
221	    use uuid::Uuid;
222	
223	    /// A well-formed `event_outbox::Model` — every malformed-row test below starts from this
224	    /// and corrupts exactly the one field its case is about.
225	    fn base_model() -> event_outbox::Model {
226	        event_outbox::Model {
227	            id: Uuid::from_u128(1),
228	            occurred_at: Utc::now(),
229	            event_type: EventType::PrincipalCreated.as_wire().to_string(),
230	            schema_version: 1,
231	            aggregate_prn: "prn:pgs:iam:::principal/00000000-0000-0000-0000-0000000000aa".to_string(),
232	            actor_prn: Some("prn:pgs:iam:::principal/00000000-0000-0000-0000-0000000000bb".to_string()),
233	            payload: serde_json::json!({"kind": "user"}).to_string(),
234	            correlation_id: Some(Uuid::from_u128(2)),
235	            published_at: None,
236	            attempts: 0,
237	            parked: false,
238	        }
239	    }
240	
241	    #[test]
242	    fn rejects_unrecognized_event_type() {
243	        let mut row = base_model();
244	        row.event_type = "iam.nope.happened".to_string();
245	        let err = row_to_domain_event(&row).unwrap_err();
246	        assert!(err.contains("unrecognized event_type"), "unexpected error: {err}");
247	    }
248	
249	    #[test]
250	    fn rejects_invalid_payload_json() {
251	        let mut row = base_model();
252	        row.payload = "{not valid json".to_string();
253	        let err = row_to_domain_event(&row).unwrap_err();
254	        assert!(err.contains("invalid payload json"), "unexpected error: {err}");
255	    }
256	
257	    #[test]
258	    fn rejects_out_of_range_schema_version() {
259	        let mut negative = base_model();
260	        negative.schema_version = -1;
261	        let err = row_to_domain_event(&negative).unwrap_err();
262	        assert!(err.contains("schema_version"), "unexpected error: {err}");
263	
264	        let mut too_large = base_model();
265	        too_large.schema_version = i32::from(u16::MAX) + 1;
266	        let err = row_to_domain_event(&too_large).unwrap_err();
267	        assert!(err.contains("schema_version"), "unexpected error: {err}");
268	    }
269	
270	    #[test]
271	    fn maps_a_well_formed_row_to_the_matching_domain_event() {
272	        let row = base_model();
273	        let ev = row_to_domain_event(&row).unwrap();
274	        assert_eq!(ev.id, row.id);
275	        assert_eq!(ev.event_type, EventType::PrincipalCreated);
276	        assert_eq!(ev.schema_version, 1);
277	        assert_eq!(ev.aggregate_prn, row.aggregate_prn);
278	        assert_eq!(ev.actor_prn, row.actor_prn);
279	        assert_eq!(ev.occurred_at, row.occurred_at);
280	        assert_eq!(ev.payload, serde_json::json!({"kind": "user"}));
281	        assert_eq!(ev.correlation_id, row.correlation_id);
282	    }
283	}
