3	//! `PgPartitionMaintainer` (SMA-467): the background task that keeps `audit_log`'s monthly leaf
4	//! partitions created ahead of time and drops aged-out ones per an outcome-aware retention policy.
5	//!
6	//! Mirrors `OutboxRelay` (`adapters::events::relay`): a `tick` does one unit of work and returns a
7	//! report; `run` is the `tokio::select!` shutdown-watch loop the composition root spawns.
8	//!
9	//! **Never stalls audit inserts.** Each DDL op runs in its OWN short transaction that first takes
10	//! `pg_advisory_xact_lock(AUDIT_PARTITION_LOCK_KEY)` (one replica does DDL at a time; same key as
11	//! m0008 so the swap and a tick never overlap) and `SET LOCAL lock_timeout` so a CREATE/DROP that
12	//! would block behind live-insert locks on the parent BACKS OFF (errors, retried next tick) instead
13	//! of queueing and stalling all audit writes (hence mutations, since committed audit rows are
14	//! in-txn). `prune` is attempted independently of `ensure_partitions_ahead`, so a create-ahead
15	//! failure (e.g. a polluted default) can't wedge retention.
16	
17	use std::future::Future;
18	use std::time::Duration;
19	
20	use chrono::{DateTime, Datelike, Utc};
21	use metrics::{counter, gauge};
22	use paigasus_observability::names;
23	use sea_orm::{ConnectionTrait, DatabaseConnection, DbErr, Statement, TransactionTrait};
24	
25	use super::migration::m0008_partition_audit_log::AUDIT_PARTITION_LOCK_KEY;
26	
27	/// The retention knobs a tick needs, decoupled from `config::RetentionConfig` (`enabled`/
28	/// `interval_secs` live in the loop, not a tick). `Copy` so tests/`run` pass it by value.
29	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
30	pub struct RetentionPolicy {
31	    pub ahead_months: u32,
32	    pub denied_months: u32,
33	    pub committed_months: u32,
34	}
35	
36	/// Per-tick outcome, returned (and logged) so tests can assert without scraping logs.
37	#[derive(Debug, Default, Clone, Copy, PartialEq, Eq)]
38	pub struct MaintenanceReport {
39	    pub created: u64,
40	    pub dropped_denied: u64,
41	    pub dropped_committed: u64,
42	    pub errored: bool,
43	}
44	
45	const LOCK_TIMEOUT: &str = "5s";
46	
47	#[derive(Clone)]
48	pub struct PgPartitionMaintainer {
49	    db: DatabaseConnection,
50	}
51	
52	impl PgPartitionMaintainer {
53	    #[must_use]
54	    pub fn new(db: DatabaseConnection) -> Self {
55	        PgPartitionMaintainer { db }
56	    }
57	
58	    /// One maintenance unit: create-ahead, then (independently) prune. Errors are logged + counted,
59	    /// never propagated — the loop keeps running.
60	    pub async fn tick(&self, now: DateTime<Utc>, policy: RetentionPolicy) -> MaintenanceReport {
61	        let mut report = MaintenanceReport::default();
62	
63	        match self.ensure_partitions_ahead(now, policy.ahead_months).await {
64	            Ok(n) => report.created = n,
65	            Err(e) => {
66	                report.errored = true;
67	                tracing::warn!(error = %e, "audit partition create-ahead failed; will retry next tick");
68	            }
69	        }
70	        // prune runs regardless of create-ahead's outcome (independence, §5.1).
71	        match self.prune(now, policy).await {
72	            Ok((d, c)) => {
73	                report.dropped_denied = d;
74	                report.dropped_committed = c;
75	            }
76	            Err(e) => {
77	                report.errored = true;
78	                tracing::warn!(error = %e, "audit partition prune failed; will retry next tick");
79	            }
80	        }
81	
82	        // Refresh the default-partition-rows gauge (the "create-ahead fell behind" signal). A
83	        // failed refresh marks the tick errored too — it's a health signal query, not fatal to
84	        // the tick's own work, but its failure means something (e.g. connection/pool trouble) is
85	        // wrong and `result="error"` should reflect that rather than silently reporting "ok".
86	        match self.default_partition_rows().await {
87	            Ok(rows) => gauge!(names::IAM_AUDIT_DEFAULT_PARTITION_ROWS).set(rows as f64),
88	            Err(e) => {
89	                report.errored = true;
90	                tracing::warn!(error = %e, "audit default-partition-rows gauge query failed");
91	            }
92	        }
93	
94	        counter!(names::IAM_AUDIT_PARTITION_MAINTENANCE_TICKS_TOTAL, "result" => if report.errored { "error" } else { "ok" }).increment(1);
95	        counter!(names::IAM_AUDIT_PARTITIONS_CREATED_TOTAL).increment(report.created);
96	        counter!(names::IAM_AUDIT_PARTITIONS_DROPPED_TOTAL, "outcome" => "denied").increment(report.dropped_denied);
97	        counter!(names::IAM_AUDIT_PARTITIONS_DROPPED_TOTAL, "outcome" => "committed").increment(report.dropped_committed);
98	        tracing::info!(
99	            created = report.created,
100	            dropped_denied = report.dropped_denied,
101	            dropped_committed = report.dropped_committed,
102	            errored = report.errored,
103	            "audit partition maintenance tick"
104	        );
105	        report
106	    }
107	
108	    /// `CREATE TABLE IF NOT EXISTS` a monthly leaf for both outcome subtrees for each month in
109	    /// `[now, now + ahead_months]`.
110	    ///
111	    /// `created` only counts leaves that did NOT already exist. Each check-then-create is done by
112	    /// [`ensure_leaf`](Self::ensure_leaf) atomically INSIDE one advisory-locked transaction — a
113	    /// prior version instead pre-fetched existing leaves via `child_leaves` once, OUTSIDE the
114	    /// lock, then created any leaf missing from that snapshot; two replicas racing the same tick
115	    /// could both observe a leaf absent (both reads happen before either takes the lock) and both
116	    /// increment `created` for the one leaf that only one of them actually creates. Checking
117	    /// existence under the same lock that guards the CREATE closes that race.
118	    async fn ensure_partitions_ahead(&self, now: DateTime<Utc>, ahead_months: u32) -> Result<u64, DbErr> {
119	        let mut created = 0;
120	        let mut ym = (now.year(), now.month());
121	        for _ in 0..=ahead_months {
122	            for sub in ["committed", "denied"] {
123	                if self.ensure_leaf(sub, ym.0, ym.1).await? {
124	                    created += 1;
125	                }
126	            }
127	            ym = add_one_month(ym);
128	        }
129	        Ok(created)
130	    }
131	
132	    /// Atomically ensure the `audit_log_<sub>_<year>_<month1>` leaf exists: within ONE
133	    /// advisory-locked transaction, check `to_regclass` for the leaf and, only if absent, issue
134	    /// the `CREATE TABLE ... PARTITION OF ...` DDL. Returns `true` iff this call created it —
135	    /// the check and the create share a lock scope so no other replica can observe the same
136	    /// "absent" state and also create (and count) it.
137	    async fn ensure_leaf(&self, sub: &str, year: i32, month1: u32) -> Result<bool, DbErr> {
138	        let leaf = format!("audit_log_{sub}_{year:04}_{month1:02}");
139	        let txn = self.db.begin().await?;
140	        txn.execute_unprepared("SET LOCAL TimeZone = 'UTC';").await?;
141	        txn.execute_unprepared(&format!("SET LOCAL lock_timeout = '{LOCK_TIMEOUT}';")).await?;
142	        txn.execute_unprepared(&format!("SELECT pg_advisory_xact_lock({AUDIT_PARTITION_LOCK_KEY});")).await?;
143	
144	        let stmt = Statement::from_string(sea_orm::DatabaseBackend::Postgres, format!("SELECT to_regclass('public.{leaf}')::text AS name"));
145	        let exists = txn.query_one(stmt).await?.and_then(|r| r.try_get::<String>("", "name").ok()).is_some();
146	
147	        let created = if exists {
148	            false
149	        } else {
150	            txn.execute_unprepared(&month_leaf_ddl(sub, year, month1)).await?;
151	            true
152	        };
153	        txn.commit().await?;
154	        Ok(created)
155	    }
156	
157	    /// Drop denied leaves older than `denied_months` and (only if `committed_months > 0`) committed
158	    /// leaves older than `committed_months`. Enumerates ACTUAL child leaves from the catalog and
159	    /// drops those whose parsed `YYYY_MM` is strictly before the cutoff month. Never drops a
160	    /// `*_default`. Returns `(dropped_denied, dropped_committed)`.
161	    async fn prune(&self, now: DateTime<Utc>, policy: RetentionPolicy) -> Result<(u64, u64), DbErr> {
162	        let mut dropped = (0u64, 0u64);
163	        for (sub, months, slot) in [("denied", policy.denied_months, 0usize), ("committed", policy.committed_months, 1usize)] {
164	            if months == 0 {
165	                continue; // 0 = never drop this outcome
166	            }
167	            let cutoff = subtract_months((now.year(), now.month()), months);
168	            for leaf in self.child_leaves(sub).await? {
169	                if let Some(ym) = parse_leaf_month(&leaf, sub)
170	                    && ym < cutoff
171	                {
172	                    self.run_ddl(&format!("DROP TABLE IF EXISTS {leaf};")).await?;
173	                    if slot == 0 { dropped.0 += 1 } else { dropped.1 += 1 }
174	                }
175	            }
176	        }
177	        Ok(dropped)
178	    }
179	
180	    /// Names of the concrete leaf partitions under `audit_log_<sub>` (excludes the default, whose
181	    /// name is `audit_log_<sub>_default` and never parses to a month).
182	    async fn child_leaves(&self, sub: &str) -> Result<Vec<String>, DbErr> {
183	        let stmt = Statement::from_string(
184	            sea_orm::DatabaseBackend::Postgres,
185	            format!("SELECT c.relname AS name FROM pg_inherits i JOIN pg_class c ON c.oid = i.inhrelid WHERE i.inhparent = 'audit_log_{sub}'::regclass"),
186	        );
187	        let rows = self.db.query_all(stmt).await?;
188	        Ok(rows.iter().filter_map(|r| r.try_get::<String>("", "name").ok()).collect())
189	    }
190	
191	    async fn default_partition_rows(&self) -> Result<i64, DbErr> {
192	        let stmt = Statement::from_string(
193	            sea_orm::DatabaseBackend::Postgres,
194	            "SELECT (SELECT count(*) FROM audit_log_committed_default) + (SELECT count(*) FROM audit_log_denied_default) + (SELECT count(*) FROM audit_log_other) AS n".to_string(),
195	        );
196	        Ok(self.db.query_one(stmt).await?.and_then(|r| r.try_get::<i64>("", "n").ok()).unwrap_or(0))
197	    }
198	
199	    /// Run one DDL statement in its own transaction under the advisory lock + a bounded
200	    /// `lock_timeout` (so it backs off rather than stalling live inserts).
201	    async fn run_ddl(&self, ddl: &str) -> Result<(), DbErr> {
202	        let txn = self.db.begin().await?;
203	        txn.execute_unprepared("SET LOCAL TimeZone = 'UTC';").await?;
204	        txn.execute_unprepared(&format!("SET LOCAL lock_timeout = '{LOCK_TIMEOUT}';")).await?;
205	        txn.execute_unprepared(&format!("SELECT pg_advisory_xact_lock({AUDIT_PARTITION_LOCK_KEY});")).await?;
206	        txn.execute_unprepared(ddl).await?;
207	        txn.commit().await
208	    }
209	
210	    /// The shutdown-watch loop (mirrors `OutboxRelay::run`): sleep `interval`, tick, repeat until
211	    /// `shutdown` resolves.
212	    pub async fn run<S>(self, policy: RetentionPolicy, interval: Duration, shutdown: S)
213	    where
214	        S: Future<Output = ()> + Send,
215	    {
216	        tokio::pin!(shutdown);
217	        loop {
218	            tokio::select! {
219	                () = tokio::time::sleep(interval) => { self.tick(Utc::now(), policy).await; }
220	                () = &mut shutdown => break,
221	            }
222	        }
223	    }
224	}
225	
226	fn month_leaf_ddl(sub: &str, year: i32, month1: u32) -> String {
227	    let (ny, nm) = add_one_month((year, month1));
228	    format!(
229	        "CREATE TABLE IF NOT EXISTS audit_log_{sub}_{year:04}_{month1:02} \
230	         PARTITION OF audit_log_{sub} \
231	         FOR VALUES FROM (TIMESTAMPTZ '{year:04}-{month1:02}-01 00:00:00+00') \
232	         TO (TIMESTAMPTZ '{ny:04}-{nm:02}-01 00:00:00+00');"
233	    )
234	}
235	
236	fn add_one_month((y, m): (i32, u32)) -> (i32, u32) {
237	    if m == 12 { (y + 1, 1) } else { (y, m + 1) }
238	}
239	
240	/// `(y, m)` shifted back by `n` months.
241	fn subtract_months((y, m): (i32, u32), n: u32) -> (i32, u32) {
242	    let total = (y * 12 + (m as i32 - 1)) - n as i32;
243	    (total.div_euclid(12), (total.rem_euclid(12) + 1) as u32)
244	}
245	
246	/// Parse `audit_log_<sub>_YYYY_MM` → `(YYYY, MM)`; `None` for the default (`…_default`) or any
247	/// non-month child.
248	fn parse_leaf_month(name: &str, sub: &str) -> Option<(i32, u32)> {
249	    let suffix = name.strip_prefix(&format!("audit_log_{sub}_"))?;
250	    let (y, m) = suffix.split_once('_')?;
251	    Some((y.parse().ok()?, m.parse().ok()?))
252	}
