258	    fn subtract_months_crosses_year_boundary() {
259	        assert_eq!(subtract_months((2026, 7), 3), (2026, 4));
260	        assert_eq!(subtract_months((2026, 2), 3), (2025, 11));
261	        assert_eq!(subtract_months((2026, 1), 1), (2025, 12));
262	    }
263	    #[test]
264	    fn parse_leaf_month_ignores_default() {
265	        assert_eq!(parse_leaf_month("audit_log_denied_2026_07", "denied"), Some((2026, 7)));
266	        assert_eq!(parse_leaf_month("audit_log_denied_default", "denied"), None);
267	    }
