19	#[tokio::main]
20	async fn main() -> anyhow::Result<()> {
21	    let config = IamConfig::load()?;
22	    config.validate().map_err(|e| anyhow::anyhow!(e))?;
23	    paigasus_logging::init("paigasus-iam", &config.log_level);
24	
25	    // A fresh/empty `authz.bootstrap_admins` is valid config (`IamConfig::validate` allows
26	    // it — spec §11), but it means a fresh deployment has no way to grant itself the first
27	    // `platform_admin` role: warn loudly rather than fail boot, since a later `moon`/`psql`
28	    // operator path can still seed one directly. Task 21b wires the actual JIT seed.
29	    if config.authz.bootstrap_admins.is_empty() {
30	        tracing::warn!("no authz.bootstrap_admins configured — a fresh deployment has no platform administrator and cannot create organizations or grant roles");
31	    }
32	
33	    // Metrics (SMA-446 Unit 3, mirrors `paigasus-gateway::main`'s identical Unit 2 wiring):
34	    // install the global Prometheus recorder only when `[metrics]` is enabled — `!enabled`
35	    // means no recorder is installed AND `/metrics` is never mounted below (a `None` handle
36	    // short-circuits both wiring blocks further down). `config.validate()` above already
37	    // rejected `metrics.addr == http_addr`.
38	    let metrics_handle = config.metrics.enabled.then(|| paigasus_observability::init("paigasus-iam"));
39	    // Register `# HELP`/`# TYPE` exposition text for every family this service emits (spec
40	    // §4.1) — only when a recorder was actually installed above; describing metrics nobody will
41	    // ever scrape is pointless, and `describe_*!` against no installed recorder is a silent
42	    // no-op anyway.
43	    if metrics_handle.is_some() {
44	        describe_iam_metrics();
45	    }
46	
47	    let db = Database::connect(&config.database_url).await?;
48	    Migrator::up(&db, None).await?;
