50	    // per-aggregate service just wraps the same underlying connection pool, and the wired
51	    // authenticator's JWKS cache/single-flight state is `Arc`-shared) — HTTP and gRPC
52	    // share one `AppState` (Task 16, SMA-442; authn wiring SMA-443). Fails fast when the
53	    // Redis JWKS cache is configured but unreachable; JWKS themselves are fetched lazily
54	    // on first use, so startup stays independent of IdP availability (spec §6.4).
55	    //
56	    // `db` itself (the original handle, not this clone) is kept alive below to build the
57	    // outbox relay (SMA-446 Slice B, Task B9) directly off the same connection pool — the
58	    // relay is wired straight in `main.rs` rather than through `AppState`, so `AppState::new`'s
59	    // signature stays unchanged.
60	    let state = AppState::new(db.clone(), &config).await?;
61	
62	    // Kept for the partition-maintenance task (SMA-467), spawned below; cloned before the outbox
63	    // relay block consumes the original `db` handle.
64	    let db_for_maintenance = db.clone();
65	
66	    let request_timeout = Duration::from_secs(30);
67	    let (tx, rx) = tokio::sync::watch::channel(());
