69	    // Same-port `/metrics` (SMA-446 Unit 3): built here, threaded into `serve_http` below, only
70	    // when enabled AND no separate `metrics.addr` is configured — `metrics.enabled = false`, or a
71	    // separate `addr`, leaves this `None` (in the `addr` case `/metrics` is served on its own
72	    // listener, spawned separately below instead).
73	    let http_metrics_router = match (&metrics_handle, config.metrics.addr) {
74	        (Some(handle), None) => Some(paigasus_observability::metrics_router(handle.clone())),
75	        _ => None,
76	    };
77	
78	    let mut servers: JoinSet<anyhow::Result<()>> = JoinSet::new();
79	    {
80	        let mut rx = rx.clone();
81	        let state = state.clone();
82	        let addr = config.http_addr;
83	        servers.spawn(async move {
84	            serve_http(addr, state, request_timeout, http_metrics_router, async move {
85	                let _ = rx.changed().await;
86	            })
