95	        // stops gracefully alongside the HTTP/gRPC servers rather than lingering past them.
96	        if let (Some(handle), Some(metrics_addr)) = (metrics_handle.clone(), config.metrics.addr) {
97	            let mut rx = rx.clone();
98	            let metrics_app = paigasus_observability::metrics_router(handle);
99	            servers.spawn(async move {
100	                let listener = tokio::net::TcpListener::bind(metrics_addr).await?;
101	                tracing::info!(%metrics_addr, "paigasus-iam metrics listener started");
