112	        let mut rx = rx.clone();
113	        let state = state.clone();
114	        let addr = config.grpc_addr;
115	        servers.spawn(async move {
116	            grpc::serve(addr, state, request_timeout, async move {
117	                let _ = rx.changed().await;
118	            })
