155	        // and surfaces a reload-task panic the same way a server-task panic would.
156	        //
157	        // `ttl`/`poll` are config-driven (`authz.policy_cache_ttl_secs`/
158	        // `authz.refresh_interval_secs`, SMA-444 Task 21) rather than the old hardcoded
159	        // `AUTHZ_POLICY_SNAPSHOT_TTL`/`AUTHZ_POLICY_RELOAD_POLL_INTERVAL` constants —
160	        // `IamConfig::validate` has already guaranteed both are non-zero.
161	        let mut rx = rx.clone();
162	        let ttl = Duration::from_secs(config.authz.policy_cache_ttl_secs);
163	        let poll = Duration::from_secs(config.authz.refresh_interval_secs);
164	        let handle = state.snapshot().spawn_reload(ttl, poll, async move {
165	            let _ = rx.changed().await;
166	        });
167	        servers.spawn(async move { handle.await.map_err(anyhow::Error::from) });
168	    }
