178	        let mut rx = rx.clone();
179	        match state.take_denial_drain() {
180	            Some(drain) => {
181	                let sink = state.audit_sink();
182	                servers.spawn(async move {
183	                    drain
184	                        .run(sink, async move {
185	                            let _ = rx.changed().await;
186	                        })
