198	        // above. Built directly off the `db` handle kept alive above (not through `AppState`) so
199	        // `AppState::new`'s signature stays unchanged; `TracingEventPublisher` (Task B8) is a
200	        // placeholder sink ahead of a real message-bus publisher (a later slice).
201	        //
202	        // `max_attempts` is `u32` in config (a natural "count" type for an operator to read/
203	        // write) but `i32` in `OutboxRelay::new` (mirroring the `event_outbox.attempts` Postgres
204	        // column) — `try_from` + clamp to `i32::MAX` rather than a wrapping `as` cast, since a
205	        // wrapped negative `max_attempts` would park every row on its very first failed publish
206	        // (`attempts >= max_attempts` true immediately), the opposite of the configured intent.
207	        if config.outbox.relay_enabled {
208	            let mut rx = rx.clone();
209	            let relay = OutboxRelay::new(
210	                db,
211	                Duration::from_secs(config.outbox.poll_interval_secs),
212	                config.outbox.batch_size,
213	                i32::try_from(config.outbox.max_attempts).unwrap_or(i32::MAX),
214	            );
215	            servers.spawn(async move {
216	                relay
217	                    .run(Arc::new(TracingEventPublisher), async move {
218	                        let _ = rx.changed().await;
219	                    })
220	                    .await;
221	                Ok(())
222	            });
223	        } else {
224	            tracing::warn!("outbox relay disabled — event_outbox rows will accrue undrained");
225	        }
226	    }
227	    {
228	        // Audit-log partition maintenance (SMA-467): create month partitions ahead and drop
229	        // aged-out denied (and, if configured, committed) leaves — mirrors the outbox relay's
230	        // spawn + shutdown-watch. Gated by `[audit.retention].enabled`; a startup run creates the
231	        // current + ahead months before the loop (non-fatal on error — the migration + the
232	        // DEFAULT partitions already backstop writes).
233	        if config.audit.retention.enabled {
234	            let policy = RetentionPolicy {
235	                ahead_months: config.audit.retention.ahead_months,
236	                denied_months: config.audit.retention.denied_months,
237	                committed_months: config.audit.retention.committed_months,
238	            };
239	            if config.audit.retention.committed_months > 0 {
240	                tracing::warn!(
241	                    committed_months = config.audit.retention.committed_months,
242	                    "audit.retention.committed_months > 0 — committed (compliance) audit partitions will be auto-dropped at this age"
243	                );
244	            }
245	            let maintainer = PgPartitionMaintainer::new(db_for_maintenance);
246	            let startup = maintainer.clone();
247	            let startup_policy = policy;
248	            // Awaited startup run (non-fatal).
249	            let report = startup.tick(chrono::Utc::now(), startup_policy).await;
250	            if report.errored {
251	                tracing::warn!("initial audit partition maintenance tick reported an error — continuing (DEFAULT partitions backstop writes)");
252	            }
253	            let interval = std::time::Duration::from_secs(config.audit.retention.interval_secs);
254	            let mut rx = rx.clone();
255	            servers.spawn(async move {
256	                maintainer
257	                    .run(policy, interval, async move {
258	                        let _ = rx.changed().await;
259	                    })
260	                    .await;
261	                Ok(())
262	            });
263	        } else {
264	            tracing::warn!(
265	                "audit.retention.enabled = false — no partition create-ahead or pruning will run; the DEFAULT partitions will fill over time and can block create-ahead until manually reattached (see RUNBOOK)"
266	            );
267	        }
268	    }
269	
270	    tracing::info!(%config.http_addr, %config.grpc_addr, "paigasus-iam started");
271	
272	    // Stop on the first of: shutdown signal, or a server task ending.
273	    let early_error: Option<anyhow::Error> = tokio::select! {
274	        () = shutdown_signal() => {
275	            tracing::info!("shutdown signal received");
276	            None
277	        }
278	        Some(joined) = servers.join_next() => {
279	            match joined {
280	                Ok(Ok(())) => {
281	                    tracing::warn!("a server task exited before shutdown was requested");
282	                    None
283	                }
284	                Ok(Err(e)) => {
285	                    tracing::error!(error = %e, "a server task failed");
286	                    Some(e)
287	                }
288	                Err(join_err) => {
289	                    tracing::error!(error = %join_err, "a server task panicked");
290	                    Some(join_err.into())
291	                }
292	            }
293	        }
294	    };
295	
296	    // Ask any still-running server to shut down gracefully.
297	    let _ = tx.send(());
298	
299	    // Drain the remaining server task(s); surface the first error.
300	    let mut result = early_error.map_or(Ok(()), Err);
301	    while let Some(joined) = servers.join_next().await {
302	        match joined {
303	            Ok(Ok(())) => {}
304	            Ok(Err(e)) if result.is_ok() => result = Err(e),
305	            Ok(Err(_)) => {}
306	            Err(join_err) if result.is_ok() => result = Err(join_err.into()),
307	            Err(_) => {}
308	        }
309	    }
310	    result
311	}
