313	/// Registers `# HELP`/`# TYPE` exposition text for the 17 metric families `paigasus-iam` emits
314	/// directly (spec §4.1; includes the SMA-467 audit partition-maintenance families), via the
315	/// `names::` consts so this can't drift from `names::ALL`, plus the 2 gRPC families via
316	/// `paigasus_observability::describe_grpc()`. Mirrors the meanings documented in
317	/// `docs/ops/RUNBOOK-observability.md` §2.1/§2.2.
318	fn describe_iam_metrics() {
319	    use metrics::{describe_counter, describe_gauge, describe_histogram};
320	
321	    describe_counter!(
322	        names::IAM_HTTP_REQUESTS_TOTAL,
323	        "HTTP requests handled by IAM's HTTP router, labeled by route, method, and status_class."
324	    );
