336	        "Every audit-log insert attempt (mutation or denial), labeled by outcome (committed/denied) and result."
337	    );
338	    describe_counter!(
339	        names::IAM_DENIAL_AUDITS_DROPPED_TOTAL,
340	        "Denial-audit rows dropped because the bounded in-memory buffer was full — non-zero means gaps in the denial audit trail."
341	    );
342	    describe_counter!(
343	        names::IAM_DENIAL_AUDITS_ENQUEUED_TOTAL,
344	        "Denial-audit rows enqueued onto the bounded in-memory buffer, whether or not the enqueue also dropped an older row."
