384	async fn shutdown_signal() {
385	    let ctrl_c = async {
386	        tokio::signal::ctrl_c().await.expect("install Ctrl+C handler");
387	    };
388	    #[cfg(unix)]
389	    let terminate = async {
390	        tokio::signal::unix::signal(tokio::signal::unix::SignalKind::terminate()).expect("install SIGTERM handler").recv().await;
391	    };
392	    #[cfg(not(unix))]
393	    let terminate = std::future::pending::<()>();
394	
395	    tokio::select! {
396	        () = ctrl_c => {},
397	        () = terminate => {},
398	    }
