3	//! `GET /v1/audit` handler (SMA-446 Task A11): a thin adapter over `AppState.audit_query` —
4	//! parse query params -> `AuditQueryService::list` -> DTO projection, no business logic here
5	//! (mirrors `grpc::audit`'s posture, and `http::authz`/`http::service_accounts`'s thin
6	//! extract -> service call -> map shape). `Action::ListAuditLog` is Root-only, enforced
7	//! INSIDE `AuditQueryService` itself (see its module doc) — a non-Root-authorized caller gets
8	//! `403 Forbidden` via `ApiError`, nothing about the audit log's contents ever reaching the
9	//! response.
10	//!
11	//! Sits on the bearer-gated `protected` sub-router (merged in `mod.rs`) — the caller's PRN
12	//! comes from the auth middleware's `AuthContext` extension, never a client-supplied value
13	//! (mirrors every other handler in this module).
14	
15	use axum::extract::{Query, State};
16	use axum::routing::get;
17	use axum::{Extension, Json, Router};
18	use chrono::{DateTime, Utc};
19	use paigasus_iam_core::{AuditFilter, AuditOutcome};
20	use paigasus_kernel::Prn;
21	use uuid::Uuid;
22	
23	use super::AppState;
24	use super::dto::{AuditListResponseDto, AuditQuery};
25	use super::error::ApiError;
26	use crate::adapters::auth::AuthContext;
27	use crate::application::error::TenancyError;
28	use crate::application::pagination::DEFAULT_LIMIT;
29	
30	pub fn router() -> Router<AppState> {
31	    Router::new().route("/v1/audit", get(list))
32	}
33	
34	/// The acting principal's canonical `Prn`, from the bearer-resolved `AuthContext` — mirrors
35	/// `adapters::http::authz::actor_prn`/`service_accounts::actor_prn`.
36	fn actor_prn(ctx: &AuthContext) -> Prn {
37	    ctx.principal_id.prn().clone()
38	}
39	
40	/// An absent or empty query param means "unfiltered" — mirrors `grpc::audit::opt_string`'s
41	/// identical empty-wire-value sentinel, generalized to HTTP's native `Option` absence too.
42	fn opt_non_empty(raw: Option<String>) -> Option<String> {
43	    raw.filter(|s| !s.is_empty())
44	}
45	
46	/// Parses the `outcome` query param: absent/empty means unfiltered; a present value must name
47	/// a known [`AuditOutcome`]. `InvalidPrn`-as-sentinel — mirrors `grpc::audit::parse_outcome`'s
48	/// identical posture (there is no dedicated error code for "not a valid outcome" either).
49	fn parse_outcome(raw: Option<String>) -> Result<Option<AuditOutcome>, TenancyError> {
50	    match opt_non_empty(raw) {
51	        None => Ok(None),
52	        Some(s) => AuditOutcome::parse(&s).map(Some).ok_or_else(|| TenancyError::InvalidPrn(format!("unknown audit outcome: {s}"))),
53	    }
54	}
55	
56	/// Parses the `cursor` query param: absent/empty means "first page" (`None`); a present value
57	/// must be a valid uuid. Mirrors `grpc::audit::parse_cursor`'s identical "not a uuid" posture.
58	fn parse_cursor(raw: Option<String>) -> Result<Option<Uuid>, TenancyError> {
59	    match opt_non_empty(raw) {
60	        None => Ok(None),
61	        Some(s) => Uuid::parse_str(&s).map(Some).map_err(|_| TenancyError::InvalidPrn("cursor must be a uuid".to_string())),
62	    }
63	}
64	
65	/// Parses an RFC3339 `from`/`to` query param: absent/empty means unfiltered; a present value
66	/// must parse as RFC3339. `InvalidPrn`-as-sentinel, mirroring `parse_outcome`/`parse_cursor`
67	/// above — there is no dedicated error code for "not a valid timestamp" either, and the gRPC
68	/// wire has no equivalent failure mode to mirror here (its `from`/`to` are already-structured
69	/// `prost_types::Timestamp`, never a string that can fail to parse).
70	fn parse_ts(raw: Option<String>) -> Result<Option<DateTime<Utc>>, TenancyError> {
71	    match opt_non_empty(raw) {
72	        None => Ok(None),
73	        Some(s) => DateTime::parse_from_rfc3339(&s)
74	            .map(|dt| Some(dt.with_timezone(&Utc)))
75	            .map_err(|_| TenancyError::InvalidPrn(format!("invalid RFC3339 timestamp: {s}"))),
76	    }
77	}
78	
79	/// Maps the query params into the kernel [`AuditFilter`] `AuditQueryService::list` consumes.
80	/// `limit` absent or `0` maps to [`DEFAULT_LIMIT`] (50) HERE — the SAME "unset sentinel ->
81	/// server default" mapping `grpc::audit::to_filter` applies to its own wire's `limit == 0`
82	/// sentinel (see that function's doc for why: passing a bare `0`/`None` straight through
83	/// would silently hit `AuditFilter::capped_limit`'s OWN floor instead, `clamp(1, MAX_LIMIT)`,
84	/// which treats "at least 1" as "unset" — a real default request would get back a single row).
85	///
86	/// Deliberately duplicated rather than shared with `grpc::audit::to_filter`: the two wire
87	/// shapes differ enough (proto's empty-string/`u32`-zero sentinels vs. HTTP's `Option`-native
88	/// query params, plus this transport's own RFC3339-string parsing with no gRPC equivalent)
89	/// that a shared helper would need its own translation layer on both sides anyway — mirrors
90	/// `grpc::audit::actor_context`'s explicit "duplicated rather than shared across a
91	/// transport-internal module boundary" posture for the identical reason.
92	fn to_filter(q: AuditQuery) -> Result<AuditFilter, TenancyError> {
93	    Ok(AuditFilter {
94	        actor_prn: opt_non_empty(q.actor),
95	        resource_prn: opt_non_empty(q.resource),
96	        action: opt_non_empty(q.action),
97	        outcome: parse_outcome(q.outcome)?,
98	        from: parse_ts(q.from)?,
99	        to: parse_ts(q.to)?,
100	        cursor: parse_cursor(q.cursor)?,
101	        limit: match q.limit {
102	            None | Some(0) => DEFAULT_LIMIT,
103	            Some(l) => l,
104	        },
105	    })
106	}
107	
108	/// `GET /v1/audit`: Root-only (enforced inside `AuditQueryService::list`, see its module doc —
109	/// a non-Root-authorized caller gets `403 Forbidden` via `ApiError`, nothing about the audit
110	/// log's contents ever reaching the response). `next_cursor` is the last returned entry's id
111	/// when the page came back FULL (a full page implies more rows may follow), else `None` — the
112	/// standard keyset-pagination "under-full page proves there is no next page" convention
113	/// (mirrors `grpc::audit::list_audit_entries`'s identical doc).
114	async fn list(State(s): State<AppState>, Extension(ctx): Extension<AuthContext>, Query(q): Query<AuditQuery>) -> Result<Json<AuditListResponseDto>, ApiError> {
115	    let actor = actor_prn(&ctx);
116	    let filter = to_filter(q)?;
117	    let limit = filter.capped_limit();
118	    let entries = s.audit_query.list(&actor, filter).await?;
119	    let next_cursor = if entries.len() as u64 == limit { entries.last().map(|e| e.id.to_string()) } else { None };
120	    Ok(Json(AuditListResponseDto {
121	        entries: entries.into_iter().map(Into::into).collect(),
122	        next_cursor,
123	    }))
124	}
